import {model,NODES,WORLDS,byNode,nodeForSkill,recordNode,interestFor,INTERESTS,novaLine,EMOTIONAL_REDIRECT} from './constellation.js';
import {novaProblem} from './nova-problems.js';
import {homeView,constellationView,evidenceView,novaAvatar,novaSpeech} from './nova-ui.js';
import {boot,currentUser,progressStore,logOut,exportJournal,listJournals,downloadJournal} from './auth.js';
import {normalize,mergeProgress} from './cloud-state.js';
import {SKILLS,DAY,dateKey,fresh,skillState,status,progress,problem,record,finishRecall,pickSkill} from './engine.js';
const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');const KEY='nerdy-pip-v1';let state=fresh();let syncKind='saved',syncMessage='Saved to your account';
let page='adventure',lesson=null,world=0,storeWarning=false;const worldNames=['Little Meadow','Canopy Grove','Wonder Lagoon','Starlight Summit'];
const icons={adventure:'<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3z"/><path d="M9 3v15m6-12v15"/>',skills:'<path d="m12 3 9 5-9 5-9-5zM3 12l9 5 9-5M3 16l9 5 9-5"/>',collection:'<rect x="4" y="7" width="16" height="14" rx="3"/><path d="M2 7h20M12 7v14M12 7C5 7 5 1 8 2c3 0 4 5 4 5s1-5 4-5c3-1 3 5-4 5"/>',parent:'<path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6z"/><path d="m8 12 3 3 5-6"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',sound:'<path d="m11 4-6 5H2v6h3l6 5zM15 8c3 2 3 6 0 8m3-11c5 4 5 10 0 14"/>',gear:'<circle cx="12" cy="12" r="4"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>'};
const icon=k=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[k]||icons.adventure}</svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){if(!currentUser())return;state.theme=document.documentElement.dataset.theme==='dark'?'dark':'light';state.world=world;progressStore.schedule(state);}
function updateSync(kind,message){syncKind=kind;syncMessage=message;document.querySelectorAll('.cloud-status').forEach(el=>{el.dataset.status=kind;el.title=message;el.textContent=kind==='saved'?'☁ Saved to your account':kind==='saving'?'☁ Saving…':'☁ Not saved · Retry';});}
function syncStrip(){return '<div class="sync-strip"><button class="cloud-status" data-action="account" data-status="'+syncKind+'" title="'+esc(syncMessage)+'">'+(syncKind==='saved'?'☁ Saved to your account':syncKind==='saving'?'☁ Saving…':'☁ Not saved · Retry')+'</button></div>';}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function legacyProgress(){try{if(localStorage.getItem('nerdy-legacy-imported'))return null;const old=JSON.parse(localStorage.getItem(KEY));return old?.attempts?.length||old?.sessions?.length?normalize(old):null;}catch{return null;}}
async function accountDialog(){
 modal.className='';const user=currentUser();if(!user)return;const legacy=legacyProgress();
 modal.innerHTML='<h2>Your account</h2><p class="account-email">'+esc(user.email)+'</p><p class="account-note" id="account-sync">'+esc(syncMessage)+'</p><div class="account-actions"><button class="secondary" id="retry-sync">Save now</button><button class="secondary" id="account-logout">Log out</button></div>'+(legacy?'<div class="legacy-import"><strong>Your earlier device progress</strong><p class="account-note">'+legacy.sessions.length+' adventures are still on this browser. Import them into this account only if they belong to you.</p><button class="text-button" id="import-progress">Import my earlier progress</button></div>':'')+'<h3 style="margin-top:24px">Saved learning journals</h3><p class="account-note">Private copies stored with your account. Export from For grown-ups to create one.</p><ul class="journal-list" id="journals"><li>Loading…</li></ul><p id="account-error" class="account-note" role="status"></p><div class="dialog-actions"><button class="primary" id="account-close">Done</button></div>';modal.showModal();
 $('#account-close').onclick=()=>modal.close();$('#retry-sync').onclick=async()=>{await progressStore.flush();$('#account-sync').textContent=syncMessage;};
 if(progressStore.error?.code==='RESET_CONFLICT'){const b=document.createElement('button');b.className='secondary';b.textContent='Download unsaved copy and load saved world';b.onclick=async()=>{b.disabled=true;try{downloadBlob(new Blob([JSON.stringify(progressStore.pending,null,2)],{type:'application/json'}),'nerdy-unsaved-progress.json');state=await progressStore.loadSaved();lesson=null;world=state.world||0;setTheme(state.theme);modal.close();render();}catch(e){$('#account-error').textContent=e.message;b.disabled=false;}};$('#account-sync').after(b);}
 $('#account-logout').onclick=async()=>{const button=$('#account-logout');button.disabled=true;try{await logOut();modal.close()}catch(e){$('#account-error').textContent=e.message;button.disabled=false;}};
 if(legacy)$('#import-progress').onclick=async()=>{const b=$('#import-progress');b.disabled=true;try{legacy.generation=state.generation||'initial';const base=fresh();base.generation=legacy.generation;state=mergeProgress(state,legacy,base);save();if(!await progressStore.flush())throw Error(syncMessage);localStorage.setItem('nerdy-legacy-imported',user.id);modal.close();render();toast('Your earlier discoveries are saved in your account.')}catch(e){$('#account-error').textContent=e.message;b.disabled=false;}};
 try{const files=await listJournals();if(!$('#journals'))return;$('#journals').innerHTML=files.length?files.map(f=>'<li><span>'+esc(new Date(f.created_at).toLocaleString())+'</span><button class="text-button" data-journal="'+esc(f.name)+'">Download</button></li>').join(''):'<li>No saved journals yet.</li>';modal.querySelectorAll('[data-journal]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{downloadBlob(await downloadJournal(b.dataset.journal),'nerdy-learning-journal.json')}catch(e){$('#account-error').textContent=e.message}finally{b.disabled=false}});}catch(e){if($('#journals'))$('#journals').innerHTML='<li>Couldn’t load journals. Reopen this window to retry.</li>';}
}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4000)}
function setTheme(value){
 const theme=value==='dark'?'dark':'light';
 document.documentElement.dataset.theme=theme;
 document.querySelector('meta[name="theme-color"]').content=theme==='dark'?'#101e1b':'#f5f8f7';
 try{localStorage.setItem('nerdy-theme',theme)}catch{toast('Theme changed for this visit. This browser cannot save the preference.')}
}
function todayCount(){return state.attempts.filter(a=>dateKey(a.at)===dateKey()&&a.ok&&!a.hint).length}
function nav(next){page=next;render();window.scrollTo(0,0)}
function render(){if(!currentUser())return;app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brandmark">n</span><span class="word">nerdy</span><small>PLAY TO GROW</small></div><nav class="nav" aria-label="Main navigation">${[['adventure','My adventure'],['skills','Constellation'],['collection','My treasures'],['parent','For grown-ups']].map(([id,name])=>`<button data-nav="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(id)}<span class="nav-label">${name}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="friend-note"><span class="leaf">✧</span>Little ideas.<br><strong>Brighter connections.</strong></div><button class="parent-nav" data-action="settings">${icon('gear')} Settings</button></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">nerdy <span class="crumb-path"> / </span><b>${{adventure:'My adventure',skills:'Constellation',collection:'My treasures',parent:'For grown-ups'}[page]}</b></div><div class="topstats"><button class="nova-header" data-action="nova" aria-label="About Nova, your AI learning spark">${novaAvatar(state,world,'small')}</button><button class="theme-toggle" data-action="theme" aria-label="${document.documentElement.dataset.theme==='dark'?'Switch to light mode':'Switch to dark mode'}" title="${document.documentElement.dataset.theme==='dark'?'Switch to light mode':'Switch to dark mode'}">${document.documentElement.dataset.theme==='dark'?'☀':'☾'}</button><div class="stat" title="Days explored — breaks never erase progress"><span>☀️</span>${state.days.length}<span class="small muted">days</span></div><div class="stat" title="Seeds earned through learning"><span>✦</span>${state.seeds}</div><button class="profile" data-action="settings" aria-label="Explorer settings">${state.avatar}</button></div></header>${syncStrip()}${page==='adventure'?home():page==='skills'?skillsPage():page==='collection'?collectionPage():parentPage()}<p class="footer-note">Made for curious minds. A little progress is a lovely thing.</p></main></div>`;bind();}
function home(){return homeView(state,world,week())}
function week(){const now=new Date(),monday=new Date(now);monday.setDate(now.getDate()-((now.getDay()+6)%7));return `<div class="week">${['M','T','W','T','F','S','S'].map((day,i)=>{const d=new Date(monday);d.setDate(monday.getDate()+i);const key=dateKey(d.getTime()),done=state.days.includes(key);return `<div class="week-day ${key===dateKey()?'today':''} ${done?'done':''}">${day}<b aria-label="${key}${done?', explored':''}">${done?'✓':key===dateKey()?'☀':'·'}</b></div>`}).join('')}</div>`}
function skillCard(s){const st=skillState(state,s.id);return `<button class="skill-card" data-start="${s.id}"><div class="skill-top"><span class="skill-symbol">${s.symbol}</span><span class="tag">${status(st)}</span></div><h3>${s.name}</h3><p>${s.desc}</p><div class="bar" aria-label="${progress(st)} percent of evidence milestones"><span style="width:${progress(st)}%"></span></div></button>`}
function skillsPage(){return constellationView(state)}
const treasures=[{icon:'🌱',name:'Little sprout',at:0,desc:'Every explorer starts somewhere.'},{icon:'🦊',name:'Meadow fox',at:1,desc:'Let your first idea take root.'},{icon:'🐸',name:'Pond pal',at:3,desc:'Let 3 ideas take root.'},{icon:'🦉',name:'Moon watcher',at:6,desc:'Let 6 ideas take root.'},{icon:'🦋',name:'Sky wanderer',at:10,desc:'Let 10 ideas take root.'},{icon:'🐉',name:'Wonder dragon',at:20,desc:'Let 20 ideas take root.'}];
function collectionPage(){return `<section class="greeting"><div><h1>A pocketful of possibilities</h1><p>Keepsakes from your discoveries. Nova is your guide in every world.</p></div><div class="day-pill">✦ ${state.seeds} seeds collected</div></section><div class="collection-grid">${treasures.map(t=>{const unlocked=treasureEarned(t);return `<div class="collectible ${unlocked?'':'locked'}"><div class="collect-icon" aria-hidden="true">${t.icon}</div><h3>${t.name}</h3><p>${t.desc}</p><button class="secondary" data-equip="${t.icon}" ${unlocked?'':'disabled'}>${unlocked?state.avatar===t.icon?'Equipped ✓':'Choose keepsake':`${Math.min(model(state).rooted,t.at)} / ${t.at} rooted ideas`}</button></div>`}).join('')}</div><div class="info">Your seeds celebrate real discoveries. There’s nothing to buy, no rewards to lose, and no timer to beat. Each adventure earns seeds for independent answers; revisiting a power earns extra.</div>`}
function parentPage(){return evidenceView(state)}
function bind(){app.querySelectorAll('[data-world]').forEach(b=>b.onclick=()=>{world=Number(b.dataset.world);save();render()});app.querySelectorAll('[data-node]').forEach(b=>b.onclick=()=>nodeDialog(b.dataset.node));app.querySelectorAll('[data-discover]').forEach(b=>b.onclick=()=>startNode(b.dataset.discover));app.querySelectorAll('[data-landmark]').forEach(b=>b.onclick=()=>landmarkDialog(Number(b.dataset.landmark)));app.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>nav(b.dataset.nav));app.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>start(b.dataset.start));app.querySelectorAll('[data-grade]').forEach(b=>b.onclick=()=>{state.grade=Number(b.dataset.grade);save();render()});app.querySelectorAll('[data-equip]').forEach(b=>b.onclick=()=>{const t=treasures.find(t=>t.icon===b.dataset.equip);if(!treasureEarned(t))return;state.avatar=t.icon;save();render();toast('Your explorer has a new keepsake.')});app.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));}
async function action(a){
 if(a==='theme'){setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');save();render();}
 if(a==='world'){world=(world+1)%4;save();render();}
 if(a==='nova')novaDialog();if(a==='interests')interestDialog();if(a==='world-story')landmarkDialog();if(a==='settings')settings();if(a==='account')await accountDialog();
 if(a==='export'){try{toast('Saving your private journal…');const body=await exportJournal(state);downloadBlob(new Blob([body],{type:'application/json'}),'nerdy-learning-journal.json');toast('Journal saved to your account and downloaded.');}catch(e){toast(e.message||'Couldn’t save the journal. Please retry.');}}
 if(a==='reset'){modal.className='';modal.innerHTML='<h2>A fresh beginning?</h2><p>This resets learning progress and treasures in your account on every device. Your login and previously exported journals stay available.</p><div class="dialog-actions"><button class="secondary" id="cancel">Keep progress</button><button class="primary" id="confirm">Reset progress</button></div>';modal.showModal();$('#cancel').onclick=()=>modal.close();$('#confirm').onclick=async()=>{const button=$('#confirm');button.disabled=true;if(!await progressStore.flush()){toast(syncMessage);button.disabled=false;return;}const next=fresh();next.name=state.name;next.grade=state.grade;next.generation=crypto.randomUUID();state=next;save();if(await progressStore.flush()){modal.close();render();toast('Your new beginning is saved.')}else{toast(syncMessage);button.disabled=false;}};}
}
function settings(){modal.className='';modal.innerHTML=`<h2>Your explorer</h2><p>Make a little room for your own way to learn.</p><label for="name">Explorer name</label><input id="name" maxlength="24" value="${esc(state.name)}" autocomplete="off"><label for="grade">Starting grade</label><select id="grade">${[0,1,2,3,4,5].map(g=>`<option value="${g}" ${g===state.grade?'selected':''}>${g?'Grade '+g:'Kindergarten'}</option>`).join('')}</select><label for="pace">Learning pace</label><select id="pace"><option value="normal" ${!state.untimed?'selected':''}>Gentle fluency · no visible timer</option><option value="untimed" ${state.untimed?'selected':''}>Comfortable pace · accuracy only</option></select><label for="appearance">Appearance</label><select id="appearance"><option value="light" ${document.documentElement.dataset.theme!=='dark'?'selected':''}>Light · Sunny meadow</option><option value="dark" ${document.documentElement.dataset.theme==='dark'?'selected':''}>Dark · Moonlit meadow</option></select><label for="sound">Celebration sounds</label><select id="sound"><option value="off" ${!state.sound?'selected':''}>Off</option><option value="on" ${state.sound?'selected':''}>On</option></select><p class="small" style="margin-top:17px">Your progress and preferences are saved to your account. Only a grown-up’s email is needed.</p><div class="dialog-actions"><button class="text-button" id="manage-account">My account</button><button class="secondary" id="cancel">Cancel</button><button class="primary" id="save-settings">Save</button></div>`;modal.showModal();$('#manage-account').onclick=()=>{modal.close();void accountDialog()};$('#cancel').onclick=()=>modal.close();$('#save-settings').onclick=()=>{state.name=$('#name').value.trim()||'Explorer';state.grade=Number($('#grade').value);state.untimed=$('#pace').value==='untimed';state.sound=$('#sound').value==='on';setTheme($('#appearance').value);save();modal.close();render()}}
function start(id){startNode(nodeForSkill(state,id))}
function startNode(node){if(!currentUser()||!byNode[node])return;modal.close();modal.className='';const m=model(state),n=m.nodes[node];world=n.world;lesson={id:n.skill,node,sessionId:crypto.randomUUID(),index:0,total:6,correct:0,seeds:0,results:[],recall:n.due,done:false,before:m.worlds.map(w=>w.unlocked),beforeReady:m.fringe.map(n=>n.id),beforePeak:n.peak};save();nextProblem();window.scrollTo(0,0)}
function nextProblem(){lesson.q=novaProblem(state,lesson.node,lesson.index);lesson.started=performance.now();lesson.hinted=false;lesson.answered=false;lesson.retries=0;renderLesson()}

function dots(n,gold=false){return `<div class="counters">${Array.from({length:Math.ceil(n/5)*5},(_,i)=>`<span class="counter ${i>=n?'empty':gold?'gold':''}"></span>`).join('')}</div>`}
function visual(v){if(!v)return '';const split=(items)=>'<div class="split-model">'+items.map(x=>'<span>'+x+'</span>').join('')+'</div>';if(v.type==='count')return dots(v.a);if(v.type==='add'||v.type==='compare')return dots(v.a)+'<span class="visual-sign">'+(v.type==='add'?'+':'or')+'</span>'+dots(v.b,true);if(v.type==='subtract')return dots(v.a)+'<span class="visual-sign">− '+v.b+'</span>';if(v.type==='groups')return Array.from({length:v.a},()=>dots(v.b)).join('');if(v.type==='fraction')return '<div class="fraction-strip">'+Array.from({length:v.b},(_,i)=>'<span class="'+(i<v.a?'fill':'')+'"></span>').join('')+'</div>';if(v.type==='equivalent')return visual({type:'fraction',a:v.a,b:v.b})+'<span class="visual-sign">=</span>'+visual({type:'fraction',a:v.a*v.c,b:v.b*v.c});if(v.type==='fraction-add')return visual({type:'fraction',a:v.a,b:v.b})+'<span class="visual-sign">+</span>'+visual({type:'fraction',a:v.c,b:v.b});if(v.type==='shape')return '<div class="shape '+v.shape+'" role="img" aria-label="'+v.shape+'"></div>';if(v.type==='place')return '<div class="place-model">'+Array(v.a).fill('<i class="place-rod" aria-label="ten"></i>').join('')+dots(v.b)+'</div>';if(v.type==='place-labels')return split([v.a+' × 100',v.b+' × 10',v.c+' × 1']);if(v.type==='decompose')return split([Math.floor(v.a/10)*10+' + '+v.a%10,'+',Math.floor(v.b/10)*10+' + '+v.b%10]);if(v.type==='area')return '<div class="area-grid" style="--cols:'+v.a+'">'+Array(v.a*v.b).fill('<i></i>').join('')+'</div>';if(v.type==='share')return dots(v.a)+'<div class="model-baskets">'+Array(v.b).fill('<span>?</span>').join('')+'</div>';if(v.type==='ruler')return split([v.a+' cm','+',v.b+' cm']);if(v.type==='convert')return split([v.a+' × 100 cm']);if(v.type==='decimal-place')return split([v.a+' ones',v.b+' tenths']);if(v.type==='decimal-split')return split([v.a+' tenths','+',v.b+' tenths']);if(v.type==='multiply-split')return split([Math.floor(v.a/10)*10+' × '+v.b,'+',v.a%10+' × '+v.b]);return ''}

function renderLesson(){const q=lesson.q,skill=byNode[lesson.node];app.innerHTML=`<main class="session"><div class="session-top"><button class="close" id="exit-lesson" aria-label="Leave adventure">×</button><div class="bar" role="progressbar" aria-valuemin="0" aria-valuemax="6" aria-valuenow="${lesson.index}" aria-label="Adventure progress"><span style="width:${lesson.index/lesson.total*100}%"></span></div><span class="stat">✦ ${lesson.seeds}</span></div><div class="lesson-meta"><span>${skill.name} · ${lesson.recall?'A little revisit':'Growing together'}</span><span>${lesson.index+1} of ${lesson.total}</span></div>${novaSpeech(state,world,lesson.recall?novaLine('review',{index:lesson.index}):lesson.index===0?'Let’s explore '+interestFor(state).name.toLowerCase()+' with a little math.':'A picture, a pattern, or a small step—choose your way.')}<section class="problem"><h1>${q.prompt}</h1>${q.display?`<div class="math-display">${q.display}</div>`:''}<div class="visual" ${q.visual&&q.visual.type!=='shape'?'aria-label="Visual math model"':''}>${visual(q.visual)}</div><button class="text-button" id="read-question">${icon('sound')} <span>Listen</span></button></section><div class="answers" role="group" aria-label="Choose your answer">${q.choices.map((c,i)=>`<button class="answer" data-answer="${i}"><span class="key">${i+1}</span>${c}</button>`).join('')}</div><div id="hint-area"></div><div class="lesson-bottom"><div class="feedback" id="feedback" aria-live="polite"><button class="secondary" id="hint-button">☼ A little help</button></div><button class="primary" id="next-question" hidden>Keep exploring ${icon('arrow')}</button></div>${syncStrip()}<p class="footer-note">Every try helps us find the next right step. ♡</p></main>`;$('#next-question').style.display='none';$('#exit-lesson').onclick=exitLesson;$('#hint-button').onclick=showHint;$('#read-question').onclick=()=>{if(!('speechSynthesis'in window)){toast('Read-aloud is not available in this browser.');return;}speechSynthesis.cancel();const text=`${q.prompt} ${q.display.replaceAll('×',' times ').replaceAll('÷',' divided by ').replaceAll('−',' minus ').replaceAll('= ?',' equals what?')}`;const u=new SpeechSynthesisUtterance(text);u.lang='en';u.rate=.8;speechSynthesis.speak(u)};app.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(Number(b.dataset.answer)));$('#next-question').onclick=advance;app.querySelectorAll('.cloud-status').forEach(b=>b.onclick=()=>void accountDialog());app.querySelectorAll('[data-action="nova"]').forEach(b=>b.onclick=novaDialog);}
function showHint(){if(!lesson||lesson.answered)return;lesson.hinted=true;$('#hint-area').innerHTML=`<div class="hint">🌱 ${lesson.q.hint}</div>`;$('#hint-button').disabled=true;}
function answer(i){if(!lesson||lesson.done||lesson.answered)return;const q=lesson.q;if(!Number.isInteger(i)||i<0||i>=q.choices.length)return;const ok=q.choices[i]===q.answer;const b=app.querySelector(`[data-answer="${i}"]`);if(b.disabled)return;b.classList.add(ok?'correct':'wrong');b.disabled=true;
 if(!lesson.retries){const a=recordNode(state,{node:lesson.node,ok,hint:lesson.hinted,ms:performance.now()-lesson.started,form:q.form,review:lesson.recall&&lesson.index<3,sessionId:lesson.sessionId});lesson.results.push(a);if(ok&&!lesson.hinted){lesson.correct++;lesson.seeds+=lesson.recall?4:3;}save();}
 if(!ok){lesson.retries++;lesson.hinted=true;$('#feedback').innerHTML='<strong>Let’s explore another idea.</strong>'+novaLine('wrong',{index:lesson.index});$('#hint-area').innerHTML=`<div class="hint">🌱 ${q.hint}</div>`;return;}
 lesson.answered=true;app.querySelectorAll('[data-answer]').forEach(x=>x.disabled=true);$('#feedback').innerHTML=`<strong>${lesson.retries?'You figured it out!':lesson.hinted?'Good thinking together!':['A little discovery!','You’ve got it!','Beautiful thinking!'][lesson.index%3]}</strong>${novaLine(lesson.retries?'retry':lesson.hinted?'hint':'correct',{index:lesson.index})}`;$('#next-question').hidden=false;$('#next-question').style.display='inline-flex';$('#next-question').textContent=lesson.index===5?'See what grew →':'Keep exploring →';$('#next-question').focus();if(state.sound)chime();}
function advance(){if(!lesson?.answered)return;lesson.index++;if(lesson.index>=lesson.total)finish();else nextProblem()}
function finish(){if(lesson.done)return;lesson.done=true;state.seeds+=lesson.seeds;if(!state.days.includes(dateKey()))state.days.push(dateKey());state.sessions.push({eventId:lesson.sessionId,id:lesson.id,node:lesson.node,at:Date.now(),correct:lesson.correct,total:lesson.total,seeds:lesson.seeds,recall:lesson.recall});save();const m=model(state),n=m.nodes[lesson.node],newPlaces=m.worlds.flatMap((w,i)=>w.landmarks.filter((_,j)=>j>=lesson.before[i]&&j<w.unlocked));const paths=m.fringe.filter(n=>!lesson.beforeReady.includes(n.id));app.innerHTML=`<main class="session finish nova-finish">${novaAvatar(state,world,'hero',m)}<div class="nova-kicker">A LITTLE MORE LIGHT</div><h1>${n.peak>lesson.beforePeak?'A new connection is glowing.':'Your thinking went somewhere.'}</h1><p>${lesson.results.some(a=>!a.ok||a.hint)?'You explored a challenge and kept going. A useful step, even when it needed a clue.':'You gave six ideas a careful try. Let’s see where they lead.'}</p><div class="finish-stats"><div><strong>+${lesson.seeds}</strong><small>Seeds earned</small></div><div><strong>${lesson.correct} / 6</strong><small>On your own</small></div><div><strong>${m.rooted}</strong><small>Ideas taking root</small></div></div>${newPlaces.length?'<div class="finish-discoveries">'+newPlaces.map(x=>'<span>✧ Discovered: '+x+'</span>').join('')+'</div>':''}${paths.length?'<div class="info">New connections: '+paths.map(n=>n.name).join(', ')+'. Your earlier ideas are helping these become ready to explore.</div>':''}${novaSpeech(state,world,n.stage==='Remembered'?'You remembered this across different days. That is what makes a lasting light.':'One adventure is one piece of evidence. We’ll meet this idea again when it helps.', 'normal',m)}<p class="nova-quiet">That can be enough for today. Your discoveries stay with you.</p><button class="primary" id="back-home">Back to my world →</button><div style="margin-top:22px"><button class="text-button" id="play-again">Another little discovery</button></div>${syncStrip()}</main>`;$('#back-home').onclick=()=>{lesson=null;nav('adventure')};$('#play-again').onclick=()=>startNode(model(state).recommendation.id);app.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));}

function exitLesson(){modal.className='';modal.innerHTML='<h2>Take a little break?</h2><p>Your learning evidence is saved. Finish this adventure to collect its seeds.</p><div class="dialog-actions"><button class="secondary" id="leave">Back to my world</button><button class="primary" id="stay">Keep exploring</button></div>';modal.showModal();$('#stay').onclick=()=>modal.close();$('#leave').onclick=()=>{modal.close();lesson=null;nav('adventure')}}
function chime(){try{const C=window.AudioContext||window.webkitAudioContext,c=new C();[523,659,784].forEach((f,i)=>{const o=c.createOscillator(),g=c.createGain();o.connect(g);g.connect(c.destination);o.frequency.value=f;g.gain.setValueAtTime(.035,c.currentTime+i*.09);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+i*.09+.23);o.start(c.currentTime+i*.09);o.stop(c.currentTime+i*.09+.24)});setTimeout(()=>c.close(),800)}catch{}}
document.addEventListener('keydown',e=>{if(modal.open||!lesson||lesson.done)return;if(['1','2','3','4'].includes(e.key)){e.preventDefault();answer(Number(e.key)-1)}});
void boot({onReady:saved=>{state=saved;world=state.nova?.introduced?(state.world||0):3;setTheme(state.theme);render();if(!state.nova?.introduced)intro();},onSignedOut:()=>{state=fresh();lesson=null;page='adventure';},onStatus:updateSync,onMerge:merged=>{state=merged;if(!lesson&&currentUser())render();}});
if(document.modelContext?.registerTool){try{void Promise.resolve(document.modelContext.registerTool({name:'read_learning_summary',description:'Read the signed-in account’s learning evidence without modifying progress.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>{if(!currentUser())throw Error('Sign in to view learning evidence.');if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw Error('This read-only tool takes an empty object.');return {sessions:state.sessions.length,discoveries:Object.values(model(state).nodes).map(n=>({id:n.id,stage:n.stage,recallChecks:n.checks}))}}})).catch(()=>{});}catch{}}


function treasureEarned(t){return model(state).rooted>=t.at||state.sessions.filter(x=>!x.node).length>=t.at;}
function dialog(content,kind=''){modal.close();modal.className=kind;modal.innerHTML=content;modal.showModal();modal.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>{modal.close();modal.className=''})}
function intro(){dialog(`${novaAvatar(state,3,'hero')}<span class="nova-kicker" style="color:#e0ccff">A SPARK FROM STARLIGHT SUMMIT</span><h2>Hello. I’m Nova.</h2><p>I’m an AI learning spark. My job is to help you become a math wonder—one little discovery at a time.</p><p>My glow grows with the ideas you learn and remember. Let’s take a little of this starlight to every world.</p><div class="dialog-actions"><button class="primary" id="meet-nova">Let’s explore →</button></div><p class="nova-quiet">I help with math. For personal worries, talk with a grown-up you trust.</p>`,'nova-intro');$('#meet-nova').onclick=()=>{state.nova.introduced=true;world=0;save();modal.close();modal.className='';render();interestDialog()};}
function novaDialog(){dialog(`${novaAvatar(state,world)}<h2>Meet Nova.</h2><p>I’m an AI learning spark, not a person. I use your math practice to suggest a helpful next step. My glow shows your growing knowledge.</p><div class="nova-text-choices"><button id="nova-worry">I’m having a hard day</button><button id="nova-interests">Choose my interests</button></div><p id="nova-response" role="status">I can help with numbers and patterns. You can take a break whenever you like.</p><p class="small muted">Nova uses programmed learning rules and reviewed responses. There’s no open chat and no personal message history.</p><div class="dialog-actions"><button class="primary" data-close>Back to exploring</button></div>`,'nova-dialog');$('#nova-worry').onclick=()=>{$('#nova-response').textContent=EMOTIONAL_REDIRECT};$('#nova-interests').onclick=interestDialog;}
function interestDialog(){let selected=[...(state.nova?.interests||['nature'])];const paint=()=>{dialog(`<h2>What sparks your curiosity?</h2><p>Choose up to three. They’ll pop up in your math discoveries. You can change these anytime.</p><div class="interest-options">${INTERESTS.map(i=>'<button class="interest-option '+(selected.includes(i.id)?'selected':'')+'" data-interest="'+i.id+'" aria-pressed="'+selected.includes(i.id)+'"><span>'+i.icon+'</span>'+i.name+'</button>').join('')}</div><div class="dialog-actions"><button class="text-button" id="clear-interests">Use nature only</button><button class="primary" id="save-interests">That’s me →</button></div>`);modal.querySelectorAll('[data-interest]').forEach(b=>b.onclick=()=>{const id=b.dataset.interest;selected=selected.includes(id)?selected.filter(x=>x!==id):selected.length<3?[...selected,id]:selected;paint()});$('#clear-interests').onclick=()=>{selected=['nature'];paint()};$('#save-interests').onclick=()=>{state.nova.interests=selected.length?selected:['nature'];save();modal.close();if(!lesson)render();};};paint();}
function nodeDialog(id){const m=model(state),n=m.nodes[id];if(!n)return;dialog(`${novaAvatar(state,n.world)}<span class="nova-kicker">${WORLDS[n.world].name}</span><h2>${n.name}</h2><p class="node-detail-status">${n.stage} · ${n.checks} successful recall checks</p><p>${n.ready?'Your earlier ideas make this a useful next step.':'You can explore this anytime. These earlier ideas can help:'}</p><div class="prereq-list">${n.prereqs.map(p=>'<button data-related="'+p+'">'+m.nodes[p].name+' · '+m.nodes[p].stage+'</button>').join('')||'<span class="small muted">A starting discovery—no earlier skills needed.</span>'}</div><p class="small muted">Helps you explore: ${NODES.filter(x=>x.prereqs.includes(id)).map(x=>x.name).join(', ')||'a growing collection of connected ideas'}.</p><div class="dialog-actions"><button class="secondary" data-close>Close</button><button class="primary" id="try-node">Let’s try it →</button></div>`,'nova-dialog');$('#try-node').onclick=()=>startNode(id);modal.querySelectorAll('[data-related]').forEach(b=>b.onclick=()=>nodeDialog(b.dataset.related));}
function landmarkDialog(index){const w=model(state).worlds[world];const i=index??Math.max(0,w.unlocked-1),earned=i<w.unlocked;dialog(`<span class="nova-kicker">${w.name}</span><h2>${w.landmarks[i]}</h2><p>${earned?w.story[i]:'This part of the world grows when your discoveries take root and you remember them on different days.'}</p><p>${earned?'This discovery is yours to keep.':'Collect '+[1,6,12][i]+' evidence milestones in this world. You have '+w.milestones+'. All math discoveries remain open while you grow.'}</p><div class="dialog-actions"><button class="primary" data-close>Keep exploring</button></div>`);}
